//! Native textarea dimensions from original HTML integer prefixes and IDL writes.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn textarea_dimensions_actual_app_prefix_sizing_pointer_paint_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-textarea-dimensions-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}textarea{position:absolute;left:20px;top:20px;font-size:12px}#reference{top:180px}#go{position:absolute;left:300px;top:20px;width:150px;height:32px}#neighbor{position:absolute;left:300px;top:100px;width:160px;height:30px}#stable{position:absolute;left:500px;top:100px}#paint{position:absolute;left:500px;top:160px;width:40px;height:30px;background:#114455}#data[cols="6"]~#paint{background:#cc2244}</style><body><textarea id=data cols=" +0012tail" rows=" +0003tail">Seed</textarea><textarea id=reference cols=12 rows=3>Reference</textarea><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><div id=paint></div><button id=go type=button>Change dimensions</button><div id=destination></div><script>var x=document.getElementById('data');document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';var focus=document.activeElement;x.cols=6;x.rows=5;if(x.cols!==6||x.rows!==5||x.getAttribute('cols')!=='6'||x.getAttribute('rows')!=='5'||x.value!=='Dirty'||x.defaultValue!=='Seed'||document.activeElement!==focus||document.getElementById('neighbor').value!=='edited neighbor')throw 'actual dimension state';document.title='TEXTAREA dimensions changed';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let target=node(&app,"data");let reference=node(&app,"reference");let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let before=app.page.controls.iter().find(|r|r.node==target).unwrap().clone();let control=app.page.controls.iter().find(|r|r.node==reference).unwrap();assert_eq!((before.width,before.height),(control.width,control.height),"HTML prefixes size like normalized attributes");
 app.forms.script_set_value(target,"Dirty").unwrap();app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&target).unwrap().value;e.cursor=3;e.anchor=1;e.offset=1;}{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+170)as usize*initial.width+510],0x114455);
 let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"TEXTAREA dimensions changed");let after=app.page.controls.iter().find(|r|r.node==target).unwrap();assert!(after.width<before.width&&after.height>before.height,"real native dimensions changed");let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+170)as usize*painted.width+510],0xcc2244);let e=&app.forms.controls[&target].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("Dirty".into(),3,1,1));let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(510,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);
}

#[test]
fn textarea_dimensions_actual_app_css_overrides_and_native_display_caps(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-textarea-dimensions-caps-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>textarea{position:absolute;left:10px;top:10px;font-size:12px}#fixed{width:70px;height:80px}#go{position:absolute;left:400px;top:20px;width:150px;height:32px}</style><textarea id=large cols=2147483647 rows=2147483647>Large</textarea><textarea id=cap cols=200 rows=100>Cap</textarea><textarea id=bad cols=2147483648 rows=2147483648>Bad</textarea><textarea id=default cols=20 rows=2>Default</textarea><textarea id=fixed cols=40 rows=8>Seed</textarea><button id=go type=button>Change fixed dimensions</button><script>var x=document.getElementById('fixed');document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';x.cols=1;x.rows=1;if(x.cols!==1||x.rows!==1||x.value!=='Seed'||x.defaultValue!=='Seed')throw 'fixed reflected state';document.title='TEXTAREA CSS dimensions retained';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let dimensions=|app:&App,id:&str|{let n=node(app,id);let r=app.page.controls.iter().find(|r|r.node==n).unwrap();(r.width,r.height)};assert_eq!(dimensions(&app,"large"),dimensions(&app,"cap"),"native display caps remain bounded");assert_eq!(dimensions(&app,"bad"),dimensions(&app,"default"),"outside 31-bit range uses defaults");let before=dimensions(&app,"fixed");let go=node(&app,"go");let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"TEXTAREA CSS dimensions retained");assert_eq!(dimensions(&app,"fixed"),before,"CSS width and height override native defaults");
}
